-- 科目1: 植物生产与环境[职高] (subject_id=32, 47个level-4知识点)
-- ════════════════════════════════════════════════════════════
SET @s=32; SET @r=(SELECT id FROM knowledge_nodes WHERE subject_id=@s AND level=1 LIMIT 1);

-- == 第1章 植物细胞与组织 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='植物细胞与组织');

-- 1.1 植物细胞的结构与功能
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='植物细胞的结构与功能');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='细胞壁/细胞膜/细胞质/细胞核 [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='叶绿体与线粒体的功能 [理解]' LIMIT 1;
SELECT id INTO @n3 FROM knowledge_nodes WHERE parent_id=@u AND name='内质网/高尔基体/核糖体 [识记]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 细胞壁/细胞膜/细胞质/细胞核\n\n【一句话定义】\n植物细胞由外到内依次为细胞壁(纤维素构成/起支持保护作用)、细胞膜(磷脂双分子层/控制物质进出)、细胞质(含细胞器的胶状物质/代谢场所)、细胞核(含DNA/遗传控制中心)。\n\n【具体例子】\n青菜叶片的绿色是因为细胞质中的叶绿体含叶绿素；西瓜成熟后果肉细胞的细胞壁变薄导致口感软烂。\n\n【考点提示·笔试】\n简答题高频考点：比较植物细胞与动物细胞的三大区别(细胞壁/液泡/质体)。选择题常考细胞壁主要成分(纤维素)和细胞膜功能(选择透过性)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 叶绿体与线粒体的功能\n\n【一句话定义】\n叶绿体是光合作用的场所(将光能→化学能,产物为葡萄糖和O2)；线粒体是呼吸作用的场所(将有机物氧化分解,释放ATP能量)。两者均为双层膜结构的细胞器,含有自身的DNA。\n\n【具体例子】\n菠菜叶片的叶肉细胞中含大量叶绿体,所以呈深绿色；小麦根尖分生区细胞无线粒体以外的质体,故为白色。马铃薯块茎细胞富含线粒体以满足发芽时的能量需求。\n\n【考点提示·笔试】\n选择/判断题高频：叶绿体=光合作用/线粒体=呼吸作用。辨析：叶绿体含有叶绿素(绿色),线粒体不含色素。' WHERE id=@n2;
UPDATE knowledge_nodes SET content='# 内质网/高尔基体/核糖体\n\n【一句话定义】\n内质网(粗面:附有核糖体→蛋白质加工/滑面:无核糖体→脂类合成)、高尔基体(扁平囊泡堆叠→蛋白质分拣包装分泌)、核糖体(无膜结构→蛋白质合成的场所)。三者协同完成分泌蛋白的合成加工运输过程。\n\n【具体例子】\n蚕的丝腺细胞分泌蚕丝蛋白,粗面内质网和高尔基体特别发达；胰腺细胞分泌消化酶,核糖体含量极高。\n\n【考点提示·笔试】\n选择题常考:核糖体是"蛋白质装配车间"，高尔基体是"分拣包装车间"。判断题注意:内质网/高尔基体有膜,核糖体无膜。' WHERE id=@n3;

-- 1.2 细胞分裂
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='细胞分裂');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='有丝分裂的过程与意义 [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='减数分裂与配子形成 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 有丝分裂的过程与意义\n\n【一句话定义】\n有丝分裂是体细胞增殖的主要方式,分为前期(染色体出现/核膜解体)、中期(染色体排列在赤道板/形态最清晰)、后期(着丝粒分裂/染色单体分开)、末期(核膜重建/细胞质分裂),最终1个母细胞→2个子细胞,染色体数不变。\n\n【具体例子】\n小麦根尖生长点细胞不断进行有丝分裂使根伸长；人皮肤擦伤后,伤口周围的表皮细胞通过有丝分裂增殖使伤口愈合。\n\n【考点提示·笔试】\n必考:识图题——给出一幅细胞分裂图,判断属于哪个时期。简记口诀:"膜仁消失显两体(前期)→形定数清赤道齐(中期)→点裂数增均两极(后期)→两消两现新壁建(末期)"。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 减数分裂与配子形成\n\n【一句话定义】\n减数分裂是形成生殖细胞(花粉/胚囊)的特殊分裂方式,染色体复制一次但连续分裂两次,最终1个母细胞→4个子细胞,染色体数减半(2n→n)。包括减数第一次分裂(同源染色体分离)和减数第二次分裂(姐妹染色单体分开)。\n\n【具体例子】\n水稻花粉母细胞(2n=24)经减数分裂形成花粉粒(n=12)；人的精原细胞(2n=46)经减数分裂形成精子(n=23)。作物杂交育种中F1代减数分裂时同源染色体分离是性状分离的细胞学基础。\n\n【考点提示·笔试】\n辨析:有丝分裂=体细胞增殖(染色体数不变)；减数分裂=生殖细胞形成(染色体数减半)。' WHERE id=@n2;

-- 1.3 植物组织类型
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='植物组织类型');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='分生组织与成熟组织的类型 [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='维管束的组成与功能 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 分生组织与成熟组织的类型\n\n【一句话定义】\n分生组织(具有持续分裂能力):顶端分生组织(根尖/茎尖→使器官伸长)、侧生分生组织(形成层/木栓形成层→使根茎加粗)。成熟组织(由分生组织分化而来不再分裂):保护组织(表皮/周皮→保护)、薄壁组织(贮藏/光合)、机械组织(厚角/厚壁→支持)、输导组织(导管/筛管→运输)、分泌组织(蜜腺/树脂道→分泌)。\n\n【具体例子】\n韭菜割了又长是因为保留了茎尖顶端分生组织；芹菜茎秆中的"筋"是厚角组织(机械组织)；桃树干上的"桃胶"来自分泌组织。\n\n【考点提示·笔试】\n必考:给一种组织名称,判断属于分生/成熟组织,以及属于成熟组织的哪个亚类。口诀:"分生分裂,保护皮,薄壁填充,机械支,输导运输,分泌泌"。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 维管束的组成与功能\n\n【一句话定义】\n维管束是植物体内的输导系统,由木质部(含导管和木纤维→运输水和无机盐/机械支持)、韧皮部(含筛管和伴胞→运输有机物)和形成层(位于两者之间→产生次生木质部和次生韧皮部)三部分组成。\n\n【具体例子】\n"树怕剥皮"是因为剥去树皮就破坏了韧皮部,根部得不到叶片制造的有机物而死亡。竹子中空是因为维管束散生在基本组织中,中心髓部在生长过程中破裂消失。\n\n【考点提示·笔试】\n高频辨析:木质部运输方向=从下到上(根→叶),运输物=水和无机盐；韧皮部运输方向=从上到下(叶→根),运输物=有机物(蔗糖)。' WHERE id=@n2;

-- == 第2章 植物的营养器官 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='植物的营养器官');

-- 2.1 根的形态与功能
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='根的形态与功能');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='直根系与须根系 [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='根尖分区(根冠/分生区/伸长区/根毛区) [理解]' LIMIT 1;
SELECT id INTO @n3 FROM knowledge_nodes WHERE parent_id=@u AND name='根的吸收作用 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 直根系与须根系\n\n【一句话定义】\n直根系(主根发达粗壮/侧根较细/有明显主次之分):大多数双子叶植物如大豆/棉花/油菜/白菜。须根系(主根不发达或早期停止生长/茎基部产生大量不定根/呈胡须状):大多数单子叶植物如小麦/水稻/玉米/葱/韭菜。\n\n【具体例子】\n拔一棵大豆可以看到明显的主根和侧根(直根系)；拔一棵小麦看到的全是粗细相近的根(须根系)。移栽树木时切断主根可促发侧根,提高成活率。\n\n【考点提示·笔试】\n必考选择题:给出一种作物名称,判断属于直根系还是须根系。口诀:"双子叶多直根(大豆棉花油菜),单子叶多须根(小麦水稻玉米)"。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 根尖分区(根冠/分生区/伸长区/根毛区)\n\n【一句话定义】\n根尖从尖端向上分为四个区域:根冠(帽状保护/分泌黏液润滑→保护分生区)、分生区(细胞小/排列紧密/分裂旺盛→产生新细胞)、伸长区(细胞迅速伸长→根生长最快的区域)、根毛区(表面密生根毛/内部已分化出导管筛管→吸收水分和无机盐的主要区域)。\n\n【具体例子】\n移栽幼苗时带土坨是为了保护根毛区和根尖不受损伤；水培植物(如绿萝)可以看到明显的根毛区(白色绒毛状)。\n\n【考点提示·笔试】\n必考识图题:给出根尖纵切图,标注四个分区并说明功能。高频:根毛区=吸收主要区域,分生区=分裂产生新细胞。' WHERE id=@n2;
UPDATE knowledge_nodes SET content='# 根的吸收作用\n\n【一句话定义】\n根通过根毛区从土壤溶液中吸收水分和无机盐。水分吸收的动力来自蒸腾拉力(被动吸水,占90%以上)和根压(主动吸水)。无机盐的吸收是主动运输过程(需要载体蛋白和能量),与水分吸收不完全同步。根对矿质元素的选择性吸收导致土壤pH值变化。\n\n【具体例子】\n施肥过多导致"烧苗"是因为土壤溶液浓度>根细胞液浓度,根不但无法吸水反而失水。水稻秧田施用(NH4)2SO4后土壤变酸(根吸收NH4+>SO42-),施用NaNO3后土壤变碱(根吸收NO3->Na+)。\n\n【考点提示·笔试】\n高频简答:"烧苗"的原因及预防措施。辨析:水分吸收=被动为主(蒸腾拉力),矿质吸收=主动为主(需要能量)。' WHERE id=@n3;

-- 2.2 茎的形态与功能
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='茎的形态与功能');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='茎的形态与分枝方式 [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='茎的初生结构与维管束 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 茎的形态与分枝方式\n\n【一句话定义】\n茎是连接根和叶的营养器官,具节和节间(叶着生处为节)。分枝方式有三种:单轴分枝(主茎顶芽持续生长→主干明显,如杨树/松树)、合轴分枝(顶芽生长一段时间后停止→侧芽代替生长→树冠开展,如苹果/桃/番茄)、假二叉分枝(顶芽停止后对生侧芽同时发育→二叉状,如丁香/辣椒)。\n\n【具体例子】\n校园里的雪松(单轴分枝→塔形树冠)；果园里的苹果树(合轴分枝→树冠圆头形)；道路两侧的丁香(假二叉分枝)。棉花整枝时保留合轴分枝有利于增加结果枝数量。\n\n【考点提示·笔试】\n选择/判断题:给植物名称或图示判断分枝方式。农业应用:果树修剪利用合轴分枝特性促进结果枝生长。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 茎的初生结构与维管束\n\n【一句话定义】\n茎的初生结构由表皮(保护)、皮层(薄壁组织/有时含厚角组织)、维管柱三部分组成。维管柱内的维管束在双子叶植物中排列成环状(有形成层→能加粗),在单子叶植物中散生于基本组织中(无形成层→不能无限加粗)。每个维管束由外方的韧皮部(运输有机物)、内方的木质部(运输水和无机盐)和中间的形成层组成。\n\n【具体例子】\n玉米茎秆比大豆茎秆粗但玉米不能像大豆那样逐年加粗(因为玉米维管束散生/无形成层)。树木横截面上可以看到年轮,是形成层季节性活动的结果(春材疏松/秋材致密)。\n\n【考点提示·笔试】\n简答题高频:"为什么玉米茎不能无限加粗而杨树能?"(单子叶vs双子叶维管束排列方式不同/有无形成层的区别)。' WHERE id=@n2;

-- 2.3 叶的形态与功能
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='叶的形态与功能');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='叶的形态与叶脉类型 [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='叶绿体与光合色素 [理解]' LIMIT 1;
SELECT id INTO @n3 FROM knowledge_nodes WHERE parent_id=@u AND name='气孔的结构与功能 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 叶的形态与叶脉类型\n\n【一句话定义】\n一片完全叶由叶片(扁平/光合作用主体)、叶柄(连接叶片与茎/支持输导)、托叶(叶柄基部的附属物/保护幼叶)三部分组成。缺少任一部分为不完全叶。叶脉是叶片中的维管束,分为网状脉(双子叶:主脉/侧脉/细脉连成网状,如大豆/棉花)和平行脉(单子叶:叶脉平行排列,如小麦/水稻/玉米)。\n\n【具体例子】\n豌豆的叶卷须是托叶变态而来,属于不完全叶。白菜的大叶片有明显的网状脉；玉米叶片上的纵条纹就是平行脉。\n\n【考点提示·笔试】\n辨析:完全叶vs不完全叶(看是否具备叶片/叶柄/托叶三部分)。网状脉=双子叶植物,平行脉=单子叶植物(偶有例外如芭蕉为平行脉但属双子叶)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 叶绿体与光合色素\n\n【一句话定义】\n叶绿体(双层膜/内有基粒和基质)主要分布在叶肉细胞中。光合色素包括叶绿素a(蓝绿色/反应中心色素)、叶绿素b(黄绿色/天线色素)、类胡萝卜素(橙黄色/辅助色素/光保护)。色素分布在基粒类囊体膜上。秋天叶片变黄是因为叶绿素分解而类胡萝卜素颜色显露。\n\n【具体例子】\n菠菜提取光合色素纸层析结果(从上到下):胡萝卜素(橙黄)→叶黄素(黄)→叶绿素a(蓝绿)→叶绿素b(黄绿)。秋天银杏叶变黄、枫叶变红(花青素积累)都是叶绿素降解的结果。\n\n【考点提示·笔试】\n判断题:叶绿素a是所有光合生物都有的色素,能将光能转化为化学能。选择题:秋天叶变黄的原因(叶绿素分解>合成,类胡萝卜素颜色显露)。' WHERE id=@n2;
UPDATE knowledge_nodes SET content='# 气孔的结构与功能\n\n【一句话定义】\n气孔是叶片表皮上由一对保卫细胞围成的小孔,是植物与外界进行气体交换(CO2进入/O2排出)和水分蒸腾的主要通道。保卫细胞壁厚度不均(靠近气孔一侧较厚/远离一侧较薄),吸水膨胀时气孔张开,失水收缩时气孔关闭。光照/K+/可溶性糖促进气孔张开,ABA(脱落酸)/黑暗/干旱促进气孔关闭。\n\n【具体例子】\n晴天上午植物气孔张开进行光合作用吸收CO2；中午强光干旱时气孔暂时关闭(午休现象)减少水分损失。小麦灌浆期遇到干热风,气孔被迫关闭,光合作用受阻导致减产。\n\n【考点提示·笔试】\n简答:气孔开闭的机理(保卫细胞吸水/失水→体积变化→气孔开/闭)。影响气孔开闭的环境因素(光/CO2浓度/水分/温度)。' WHERE id=@n3;

-- 2.4 营养器官的变态
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='营养器官的变态');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='根的变态(贮藏根/气生根) [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='茎的变态(块茎/根茎/鳞茎) [识记]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 根的变态(贮藏根/气生根)\n\n【一句话定义】\n根变态是根在长期适应环境过程中形态结构发生变异的现象。常见类型:贮藏根(主根或侧根膨大贮藏养分→萝卜/胡萝卜/甘薯/甜菜)、气生根(生长在空气中的不定根→玉米支柱根/常春藤攀援根/红树呼吸根)、寄生根(菟丝子/列当→伸入寄主体内吸收养分)。\n\n【具体例子】\n萝卜的食用部分是肉质直根(由主根膨大形成)；甘薯的食用部分是块根(由侧根或不定根膨大形成)。玉米茎基部伸入土中的不定根起支撑防倒伏作用。\n\n【考点提示·笔试】\n辨析高频:萝卜(肉质直根)vs甘薯(块根)——前者由主根形成/后者由侧根不定根形成。玉米支柱根属于气生根→不定根。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 茎的变态(块茎/根茎/鳞茎)\n\n【一句话定义】\n茎变态是茎在长期适应环境过程中形态结构发生变异的现象。常见类型:块茎(马铃薯→膨大的地下茎/有芽眼/芽眼呈螺旋排列)、根茎(莲藕/生姜→横走地下茎/有节和节间/节上有鳞叶和不定根)、鳞茎(洋葱/大蒜→扁平盘状茎/外围多层肥厚鳞叶)、球茎(荸荠/慈姑/芋头→球形地下茎/节上具鳞叶)。\n\n【具体例子】\n马铃薯块茎上的"芽眼"就是节,芽眼内的小芽是腋芽——证明块茎是茎的变态而非根的变态。切马铃薯种薯时每块至少保留一个芽眼。洋葱切开后最底部坚硬的盘状结构就是茎(鳞茎盘)。\n\n【考点提示·笔试】\n必考:判断萝卜/甘薯/马铃薯/莲藕/洋葱各属于根变态还是茎变态。口诀:"萝卜甘薯根变态,土豆莲藕洋葱茎"——判断依据:有无节和芽(茎变态有节和芽,根变态无)。' WHERE id=@n2;

-- == 第3章 植物的生殖器官 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='植物的生殖器官');

-- 3.1 花的形态与发育
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='花的形态与发育');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='花的基本组成(花萼/花冠/雄蕊群/雌蕊群) [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='传粉与受精过程 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 花的基本组成(花萼/花冠/雄蕊群/雌蕊群)\n\n【一句话定义】\n一朵完全花由四部分组成:花萼(最外层/绿色萼片→保护花蕾)、花冠(第2层/彩色花瓣→吸引传粉者)、雄蕊群(第3层/花丝+花药→产生花粉粒/雄性生殖)、雌蕊群(最内层/子房+花柱+柱头→接受花粉/胚珠发育为种子/雌性生殖)。花萼+花冠合称花被。缺少任一部分为不完全花。\n\n【具体例子】\n桃花是完全花的典型代表(萼片5/花瓣5/雄蕊多数/雌蕊1)。黄瓜的雄花缺少雌蕊、雌花缺少雄蕊→均为不完全花(单性花)。油菜花有4个萼片4个花瓣(十字花冠),6个雄蕊(四强雄蕊)。\n\n【考点提示·笔试】\n必考辨析:完全花vs不完全花、两性花vs单性花。识图题:标注花的结构(萼片/花瓣/雄蕊/雌蕊/花托)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 传粉与受精过程\n\n【一句话定义】\n传粉是花粉从花药传到柱头上的过程,分为自花传粉(同一朵花内/同株异花间,如水稻/小麦/大豆)和异花传粉(不同植株间,如玉米/白菜/向日葵)。受精是花粉管进入胚囊后,一个精子与卵细胞结合形成受精卵(2n→发育为胚),另一个精子与极核结合形成受精极核(3n→发育为胚乳)——称为双受精(被子植物特有)。\n\n【具体例子】\n玉米田周围种植高秆作物作为隔离带防止不同品种串粉(异花传粉作物需隔离)。苹果园放养蜜蜂增加传粉率提高坐果率。\n\n【考点提示·笔试】\n必考:双受精的概念和生物学意义(胚乳也为杂合→增强后代生活力)。自花传粉(闭花传粉如豌豆/花生)vs异花传粉(风媒花/虫媒花的适应特征)。' WHERE id=@n2;

-- 3.2 种子的结构与萌发
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='种子的结构与萌发');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='双子叶与单子叶种子的结构 [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='种子萌发的条件 [掌握]' LIMIT 1;
SELECT id INTO @n3 FROM knowledge_nodes WHERE parent_id=@u AND name='发芽率与发芽势的计算 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 双子叶与单子叶种子的结构\n\n【一句话定义】\n双子叶无胚乳种子(大豆/花生/棉花):由种皮和胚(胚芽+胚轴+胚根+2片子叶)组成,营养物质贮藏在肥厚的子叶中。单子叶有胚乳种子(小麦/水稻/玉米):由果皮和种皮愈合而成的种皮、胚乳(贮藏淀粉)、胚(胚芽+胚根+胚轴+1片子叶(盾片吸收胚乳养分))组成。\n\n【具体例子】\n浸种后剥开大豆种子,两片肥大的豆瓣就是子叶(贮藏蛋白质和脂肪)；切开玉米种子滴加碘液,胚乳变蓝(含淀粉),而胚不变蓝。花生仁外面的红衣是种皮,两瓣白色的是子叶。\n\n【考点提示·笔试】\n必考识图:大豆种子和玉米种子的纵切结构标注。高频辨析:双子叶无胚乳种子(营养物质在子叶)vs单子叶有胚乳种子(营养物质在胚乳)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 种子萌发的条件\n\n【一句话定义】\n种子萌发需同时满足内部条件(种胚完整/度过休眠期/种子有活力)和外部条件(充足水分使种皮软化酶活化/适宜温度(多数作物15~30℃)/充足氧气供呼吸作用需能)。大多数种子萌发不需要光照(少数需光种子如烟草/莴苣,少数嫌光种子如洋葱/百合)。\n\n【具体例子】\n播种前晒种/浸种可打破休眠促进萌发；播种过深导致种子缺氧,出苗率下降；早春地膜覆盖可提高地温促进萌发。水稻浸种催芽时勤换水是保证氧气供应防止无氧呼吸烂种。\n\n【考点提示·笔试】\n简答高频:种子萌发的内外部条件(至少各写3点)。判断题:所有种子萌发都需要光照(×)/种子萌发需要氧气(√)。' WHERE id=@n2;
UPDATE knowledge_nodes SET content='# 发芽率与发芽势的计算\n\n【一句话定义】\n发芽率(%)=规定天数内发芽种子数/供试种子总数×100%,反映种子发芽的总体能力。发芽势(%)=规定前期(一般3~5天)内发芽种子数/供试种子总数×100%,反映种子发芽的整齐度和活力。例如:100粒种子,3天内发芽60粒,7天内共发芽85粒→发芽势=60%,发芽率=85%。\n\n【具体例子】\n购买种子时看包装上的发芽率(国标要求主要作物≥85%)；播种量计算:实际播种量=理论播种量÷发芽率。如小麦理论播量10kg/亩,发芽率80%,实际需播12.5kg/亩。\n\n【考点提示·笔试】\n必考计算题:给出发芽试验数据求发芽率和发芽势。公式记忆:"率看终,势看前"(发芽率看最终天数,发芽势看前期天数)。' WHERE id=@n3;

-- 3.3 果实的发育与类型
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='果实的发育与类型');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='果实的类型与发育 [识记]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 果实的类型与发育\n\n【一句话定义】\n果实由受精后子房发育而来(子房壁→果皮/胚珠→种子)。分类:(1)真果(仅由子房发育→桃/大豆/番茄)与假果(子房+花托/花萼等共同发育→苹果/梨/草莓/西瓜)；(2)单果(一朵花一个雌蕊形成一个果实→桃/杏)、聚合果(一朵花多个离生雌蕊各发育为小果聚生在花托上→草莓/莲蓬)、聚花果(整个花序发育为一个果实→桑葚/菠萝/无花果)。\n\n【具体例子】\n吃苹果时果肉部分由花托发育而来(假果),中心"苹果核"才是子房发育的真果部分。草莓表面的"小芝麻粒"才是真正的果实(瘦果),红色肉质部分是膨大的花托。\n\n【考点提示·笔试】\n辨析高频:真果vs假果(看食用部分来源)；单果vs聚合果vs聚花果(看一朵花/多朵花)。举例判断:桃=真果单果,草莓=聚合果,桑葚=聚花果。' WHERE id=@n1;

-- == 第4章 植物生理代谢 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='植物生理代谢');

-- 4.1 水分代谢
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='水分代谢');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='水分吸收与运输途径 [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='蒸腾作用的概念与调节 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 水分吸收与运输途径\n\n【一句话定义】\n水分从土壤→根毛(渗透吸水)→根的皮层→内皮层→中柱鞘→木质部导管→茎导管→叶脉导管→叶肉细胞→细胞间隙→气孔下腔→气孔→大气(蒸腾作用散失)。水在导管中运输的连续性是靠"蒸腾拉力-内聚力-张力"(蒸腾拉力提供动力/水分子间的内聚力维持水柱连续/导管壁承受张力)。\n\n【具体例子】\n高大树木(如杨树高30m)能将水从根运到树梢,靠的就是蒸腾拉力(太阳是最终动力)。切花插入水中仍能保持鲜艳是因为导管中的水柱连续性。\n\n【考点提示·笔试】\n简答:水分从土壤进入根毛再到叶片的运输途径(依次经过的结构)。选择题:水分在植物体内运输的主要动力是蒸腾拉力。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 蒸腾作用的概念与调节\n\n【一句话定义】\n蒸腾作用是水分以气体状态通过植物体表(主要是叶片气孔)散失到大气中的过程。意义:(1)产生蒸腾拉力→水分向上运输的动力(2)降低叶温(防止灼伤)(3)促进矿质元素的吸收和运输。气孔是蒸腾的主要通道(占90%以上),角质层蒸腾和皮孔蒸腾占少部分。\n\n【具体例子】\n夏天中午植物叶片萎蔫是因为蒸腾失水>根系吸水(暂时萎蔫傍晚恢复)；干热风天气小麦青枯逼熟是因为蒸腾过强导致植株脱水。\n\n【考点提示·笔试】\n简答高频:蒸腾作用的生理意义(至少写3点)。辨析:蒸腾作用vs蒸发(蒸腾=植物生理过程受气孔调节,蒸发=纯物理过程)。' WHERE id=@n2;

-- 4.2 矿质营养
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='矿质营养');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='16种必需元素与缺素症识别 [掌握]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='氮磷钾的生理作用与缺乏症状 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 16种必需元素与缺素症识别\n\n【一句话定义】\n植物必需元素有16种:大量元素9种(C/H/O/N/P/K/Ca/Mg/S),微量元素7种(Fe/Mn/B/Zn/Cu/Mo/Cl)。判断标准(三要素):(1)缺乏该元素植物不能完成生活史(2)不能被其他元素替代(3)直接参与植物代谢。缺素症状:老叶先显症=N/P/K/Mg(可移动元素→从老叶转运到新叶)；新叶先显症=Ca/S/Fe/B(难移动元素→无法从老叶转运)。\n\n【具体例子】\n油菜缺硼"花而不实"(只开花不结籽)；果树缺铁新叶黄化(叶脉仍绿)；番茄缺钙脐腐病(果实顶端变黑凹陷)。\n\n【考点提示·笔试】\n必考:(1)口诀记忆大量元素"C HOPKNS CaFe Mg"(C/H/O/P/K/N/S/Ca/Fe/Mg)各字母代表。(2)缺素症首先出现的部位(老叶/新叶)取决于元素在植物体内的移动性。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 氮磷钾的生理作用与缺乏症状\n\n【一句话定义】\n氮(N):蛋白质和叶绿素的组成成分→促进营养生长/使叶片浓绿。缺N:老叶先黄化/植株矮小/产量低。过N:徒长/贪青晚熟/倒伏/病虫害加重。磷(P):核酸和ATP的组成成分→促进根系发育/花芽分化/提高抗逆性。缺P:老叶暗绿或紫红色(花青素积累)/根系弱/分蘖少。钾(K):以离子态存在→促进光合产物运输/提高抗倒伏和抗病性。缺K:老叶叶尖和叶缘焦枯/茎秆软弱易倒伏。\n\n【具体例子】\n小麦缺氮→老叶从叶尖向基部黄化；玉米缺磷→幼苗茎基部变紫红色(俗称"红苗")；棉花缺钾→叶片边缘焦枯呈"金边"状,棉铃小吐絮不畅。\n\n【考点提示·笔试】\n必考简答:氮/磷/钾各写2~3个生理作用+1~2个缺素症状。N=叶肥(长叶子),P=花果肥(促花果根),K=茎肥(壮秆抗倒)。' WHERE id=@n2;

-- 4.3 光合作用
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='光合作用');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='光反应与暗反应的过程 [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='光合作用的影响因素与生产应用 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 光反应与暗反应的过程\n\n【一句话定义】\n光合作用总方程式:6CO2+12H2O→光能/叶绿体→C6H12O6+6O2+6H2O。分为两个阶段:(1)光反应(类囊体膜上/需光):水光解(2H2O→4H++4e-+O2↑)+光合磷酸化(ADP+Pi→ATP)+NADPH生成(NADP++2e-+H+→NADPH)；(2)暗反应/卡尔文循环(基质中/不需光但需酶):CO2固定(C5+CO2→2C3)→C3还原(需ATP和NADPH)→C5再生。光反应为暗反应提供ATP和NADPH。\n\n【具体例子】\n温室大棚在阴天补光(促进光反应)；增施CO2气肥(促进暗反应/CO2固定)。\n\n【考点提示·笔试】\n简答:比较光反应与暗反应(场所/条件/原料/产物)。判断:光合作用释放的O2来自H2O而非CO2(鲁宾和卡门的同位素示踪实验)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 光合作用的影响因素与生产应用\n\n【一句话定义】\n影响光合速率的主要因素:光照强度(光饱和点/光补偿点→合理密植避免相互遮光)、CO2浓度(大气约0.035%/C3植物CO2补偿点约50ppm/C4植物几乎为0)、温度(适温25~30℃/过高→酶失活/过低→酶活性低)、水分(缺水→气孔关闭→CO2进入受阻→光合↓)、矿质营养(N/Mg是叶绿素成分/K调节气孔开闭)。\n\n【具体例子】\n玉米(C4植物)比小麦(C3植物)更耐高温强光,因为C4植物有"CO2泵"机制提高维管束鞘细胞CO2浓度。温室大棚冬季补光+增温+增施CO2三者配合提高光合效率。合理密植原则:"封行不封顶"(叶片相互接触但不过度重叠)。\n\n【考点提示·笔试】\n高频:给出生产措施分析其增产的光合生理原理。如:合理密植→改善光照条件；施CO2气肥→增加光合原料；正其行通其风→改善CO2供应。' WHERE id=@n2;

-- 4.4 呼吸作用
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='呼吸作用');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='有氧呼吸与无氧呼吸比较 [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='呼吸作用在农产品贮藏中的应用 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 有氧呼吸与无氧呼吸比较\n\n【一句话定义】\n有氧呼吸:C6H12O6+6O2→6CO2+6H2O+2870kJ(38ATP),在细胞质基质(糖酵解)+线粒体(三羧酸循环+电子传递链)中进行。无氧呼吸(发酵):C6H12O6→2C2H5OH+2CO2+226kJ(2ATP)(酒精发酵/酵母和多数植物)或C6H12O6→2C3H6O3+197kJ(2ATP)(乳酸发酵/马铃薯块茎/玉米胚)。有氧呼吸能量效率是无氧呼吸的19倍。\n\n【具体例子】\n水稻淹水时间过长→根系无氧呼吸产生酒精→根系变黑腐烂(酒精毒害)。马拉松运动员腿部肌肉剧烈运动时进行乳酸发酵→肌肉酸痛。\n\n【考点提示·笔试】\n必考:写出有氧呼吸和酒精发酵的化学反应方程式。判断:有氧呼吸能量效率远高于无氧呼吸(前者38ATP,后者2ATP)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 呼吸作用在农产品贮藏中的应用\n\n【一句话定义】\n农产品贮藏的基本原则是降低呼吸速率以延长贮藏期(呼吸消耗有机物→品质下降/失重)。措施:(1)降低温度(0~4℃冷藏/但热带水果如香蕉不宜低于10℃否则冷害)(2)降低O2浓度(气调贮藏:O2 2%~5%)增加CO2浓度(3%~5%)(3)控制水分(谷物安全含水量12%~14%以下)(4)减少机械损伤(损伤引起呼吸跃变上升)。\n\n【具体例子】\n苹果冷库贮藏(0~2℃/湿度90%/O2 3%+CO2 3%气调)可存6~8个月。甘薯贮藏温度10~15℃(过低冷害,过高发芽)。粮食入库前必须晒干至安全含水量(小麦12.5%/稻谷13.5%/玉米14%)。\n\n【考点提示·笔试】\n简答:农产品贮藏保鲜的原理和主要措施。辨析:有氧呼吸vs无氧呼吸哪种对贮藏危害大(无氧→产生酒精使品质恶化)。' WHERE id=@n2;

-- == 第5章 植物生长发育 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='植物生长发育');

-- 5.1 植物激素与调节剂
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='植物激素与调节剂');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='五大激素(生长素/赤霉素/细胞分裂素/脱落酸/乙烯) [掌握]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='植物生长调节剂的应用 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 五大激素(生长素/赤霉素/细胞分裂素/脱落酸/乙烯)\n\n【一句话定义】\n(1)生长素(IAA):促进细胞伸长/顶端优势/诱导插条生根。合成部位:茎尖/幼叶/发育中的种子。(2)赤霉素(GA):促进茎伸长(使矮生植物长高)/打破种子休眠/促进α-淀粉酶合成(啤酒发芽)。(3)细胞分裂素(CTK):促进细胞分裂和芽分化/延缓叶片衰老。合成部位:根尖。(4)脱落酸(ABA):促进休眠/促进脱落/促进气孔关闭(抗逆激素)。(5)乙烯(ETH):气体激素→促进果实成熟/促进器官脱落(衰老激素)。\n\n【具体例子】\n用生长素处理扦插枝条促进生根；用赤霉素处理使无核葡萄果实增大；香蕉在密闭袋中自身释放乙烯加速成熟(自催熟)。\n\n【考点提示·笔试】\n必考简答:五大激素的名称+各写1个主要生理作用。口诀:"生长促长顶,赤霉拔高节,分裂促芽生,脱落抗逆助,乙烯催熟落"。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 植物生长调节剂的应用\n\n【一句话定义】\n植物生长调节剂是人工合成的具有植物激素活性的化学物质。常见应用:(1)促进扦插生根→NAA(萘乙酸)/IBA(吲哚丁酸)(2)防止落花落果→2,4-D/防落素用于番茄茄子(3)促进果实成熟→乙烯利(释放乙烯)用于香蕉/柿子催熟(4)培育壮苗→多效唑/矮壮素抑制茎伸长(5)打破休眠→赤霉素处理马铃薯种薯促发芽。\n\n【具体例子】\n番茄蘸花用2,4-D可防止低温落花提高坐果率(浓度过高导致畸形果)。棉花喷洒乙烯利促进棉铃开裂吐絮。水稻秧苗喷多效唑→矮壮分蘖多(培育壮秧)。\n\n【考点提示·笔试】\n简答:至少写3种植物生长调节剂的名称+应用。注意:浓度是关键(低促高抑)。' WHERE id=@n2;

-- 5.2 植物生长的周期性
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='植物生长的周期性');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='昼夜周期与季节周期 [识记]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='顶端优势与根冠比 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 昼夜周期与季节周期\n\n【一句话定义】\n植物生长随昼夜和季节变化呈现规律性变化。(1)昼夜周期:白天生长慢(高温/强光抑制生长素/水分亏缺),夜间生长快(温度适宜/水分充足/生长素活性高)。(2)季节周期:温带植物春季萌芽→夏季旺盛生长→秋季生长减缓/落叶→冬季休眠。这是植物长期适应环境形成的节律,受光周期和温周期调控。\n\n【具体例子】\n竹笋夜间生长速度明显快于白天(一夜可长高几十厘米)。落叶树木秋季落叶进入休眠是对冬季低温干旱的适应。冬小麦必须经过冬季低温(春化)才能抽穗。\n\n【考点提示·笔试】\n判断:植物夜间生长比白天快(√)。落叶树木秋季落叶是季节周期的表现(√)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 顶端优势与根冠比\n\n【一句话定义】\n顶端优势:主茎顶芽生长抑制侧芽生长的现象(顶芽产生的生长素向下极性运输→侧芽处生长素浓度过高→抑制侧芽生长→越靠近顶端的侧芽受抑制越强)。去除顶芽→顶端优势解除→侧芽萌发。根冠比(R/S):植物地下部分(根)与地上部分(茎叶)干重的比值,反映光合产物在根和茎叶间的分配比例。\n\n【具体例子】\n棉花打顶(去除主茎顶芽)→侧枝萌发增加果枝数→增产。水稻晒田→促进根系下扎→根冠比增大→提高抗倒伏能力。苗木移栽时修剪部分枝叶→减少蒸腾/提高成活率(但根冠比暂时增大)。\n\n【考点提示·笔试】\n简答:顶端优势的机理(生长素极性运输→侧芽生长素浓度过高受抑)。实际应用:果树修剪/棉花打顶/茶树采摘的原理。' WHERE id=@n2;

-- 5.3 成花生理
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='成花生理');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='春化作用的概念与应用 [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='光周期现象(长日/短日/日中性植物) [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 春化作用的概念与应用\n\n【一句话定义】\n春化作用:某些植物必须经过一定时间的低温(0~10℃)诱导才能从营养生长转向生殖生长(抽穗/开花)的现象。冬性作物(冬小麦)需要低温春化,春性作物(春小麦/春油菜)不需要。种子吸胀后或幼苗期接受低温均可完成春化。春化效果可以被高温(>30℃)解除(脱春化)。\n\n【具体例子】\n冬小麦秋播→冬季自然低温完成春化→次年春季抽穗开花。若春播冬小麦→无法通过低温春化→只长叶不抽穗。农业生产中"闷麦"(种子吸水后低温处理)可人工完成春化。\n\n【考点提示·笔试】\n简答:冬小麦春播为何不能抽穗?(未通过春化作用)。辨析:冬性/春性品种的区别(是否需要低温春化)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 光周期现象(长日/短日/日中性植物)\n\n【一句话定义】\n植物对昼夜长短(光周期)变化发生反应的现象称为光周期现象。长日植物(LDP):日照长度长于临界日长时开花(小麦/菠菜/油菜/萝卜/甜菜)。短日植物(SDP):日照长度短于临界日长时开花(菊花/大豆/水稻/烟草/一品红)。日中性植物(DNP):开花不受日照长度影响(番茄/黄瓜/辣椒/四季豆)。感受光周期的部位是叶片(非生长点)。\n\n【具体例子】\n菊花是短日植物(秋季开花),若秋季夜间路灯照射→间断暗期→推迟开花。大棚种植可通过补光(长日植物)或遮光(短日植物)调控花期,实现反季节上市。\n\n【考点提示·笔试】\n必考:给定植物名称判断长日/短日/日中性。如小麦=长日/菊花=短日/番茄=日中性。判断:感受光周期的部位是叶片(√)不是茎尖(×)。' WHERE id=@n2;

-- == 第6章 土壤与肥料 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='土壤与肥料');

-- 6.1 土壤基本性质
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='土壤基本性质');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='土壤质地(砂土/壤土/黏土) [掌握]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='土壤有机质与pH值 [理解]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 土壤质地(砂土/壤土/黏土)\n\n【一句话定义】\n土壤质地是按土壤中不同粒径颗粒(砂粒2~0.02mm/粉粒0.02~0.002mm/黏粒<0.002mm)的相对比例划分的土壤类型。砂土(砂粒>50%):通透性好/保水保肥差/易干旱/升温快(热性土)→适合种花生/甘薯/西瓜。黏土(黏粒>30%):保水保肥强/通透性差/耕作困难/升温慢(冷性土)→适合种水稻。壤土(砂黏适中):兼有两者的优点/水肥气热协调最好→最理想的农业土壤。\n\n【具体例子】\n田间手测法:砂土搓不成条、壤土可搓成条但弯曲断裂、黏土可搓成细条并可弯成环不裂。\n\n【考点提示·笔试】\n必考简答:比较砂土、壤土、黏土的农业生产特性(至少各写2个特点)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 土壤有机质与pH值\n\n【一句话定义】\n土壤有机质(包括动植物残体/微生物/腐殖质)是土壤肥力的核心,作用:(1)提供矿质养分(分解后释放N/P/S等)(2)改善土壤结构(形成团粒结构)(3)提高保水保肥能力(腐殖质吸附力强)(4)缓冲土壤pH变化。土壤pH(酸碱度)影响养分有效性:大多数作物适宜pH 6.0~7.5,过酸(pH<5.5)导致Al3+/Mn2+毒害和P固定,过碱(pH>8.0)导致Fe/Zn/Mn/B有效性降低。\n\n【具体例子】\n长期施用有机肥的菜园土颜色深黑、疏松透气(腐殖质含量高)。南方红壤(pH 4.5~5.5)需施石灰改良酸性。\n\n【考点提示·笔试】\n简答:土壤有机质的作用(至少写3点)。选择:作物适宜的土壤pH范围(6.0~7.5或中性偏酸)。' WHERE id=@n2;

-- 6.2 土壤肥力与管理
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='土壤肥力与管理');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='土壤肥力四因素(水/肥/气/热) [理解]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='土壤耕性与宜耕期 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 土壤肥力四因素(水/肥/气/热)\n\n【一句话定义】\n土壤肥力是土壤供给植物生长发育所需的水分、养分、空气和热量的综合能力。水(土壤溶液中的水分→溶解养分/运输介质/参与代谢)、肥(矿质养分→N/P/K等元素供给)、气(土壤空气中的O2→根系呼吸/微生物活动/CO2浓度过高会毒害根系)、热(土壤温度→影响种子萌发/根系生长/微生物活性)。四因素相互联系相互制约,理想的肥沃土壤应具良好的"水肥气热"协调能力。\n\n【具体例子】\n雨后中耕松土破除板结→改善通气和水分状况(水气协调)。温室大棚冬季灌溉温水→提高地温(调节热因素)。\n\n【考点提示·笔试】\n必考:简述土壤肥力四因素及相互关系。判断:团粒结构是土壤肥力的物质基础(√)。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 土壤耕性与宜耕期\n\n【一句话定义】\n土壤耕性(适耕性)是指土壤在耕作时表现出来的物理性质(黏着性/可塑性/坚实度)。土壤含水量适当时耕性最佳(阻力小/土垡易碎/不起坷垃)。宜耕期(适耕含水量范围):砂土宽(几乎随时可耕)、壤土中等(雨后2~3天)、黏土窄(雨后需及时耕,稍干即过硬)。田间判断:"手握成团,落地即散"为适耕状态。\n\n【具体例子】\n黏土地雨后不能立即耕地(过湿→犁后起明条/干了变硬坷垃),须等表土稍白(适耕期)时抢耕。砂土地即使刚下过雨也可耕作(渗水快/宜耕期很宽)。\n\n【考点提示·笔试】\n判断:黏土的宜耕期比砂土窄(√)。田间判断适耕状态:手握成团/落地即散。' WHERE id=@n2;

-- 6.3 肥料种类与施用
SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='肥料种类与施用');
SELECT id INTO @n1 FROM knowledge_nodes WHERE parent_id=@u AND name='化肥种类(氮/磷/钾/复合肥) [掌握]' LIMIT 1;
SELECT id INTO @n2 FROM knowledge_nodes WHERE parent_id=@u AND name='有机肥(粪尿肥/堆肥/绿肥) [理解]' LIMIT 1;
SELECT id INTO @n3 FROM knowledge_nodes WHERE parent_id=@u AND name='施肥方法与测土配方 [掌握]' LIMIT 1;
UPDATE knowledge_nodes SET content='# 化肥种类(氮/磷/钾/复合肥)\n\n【一句话定义】\n(1)氮肥:尿素CO(NH2)2(含N46%/中性肥/可作基追叶面肥)、碳铵NH4HCO3(含N17%/易挥发/宜深施覆土)、硫酸铵(NH4)2SO4(生理酸性肥/含N21%)。(2)磷肥:过磷酸钙(普钙/含P2O5 12%~18%/水溶性磷/易被土壤固定)、钙镁磷肥(枸溶性磷/适合酸性土壤)。(3)钾肥:氯化钾KCl(含K2O 50%~60%/生理酸性/忌氯作物慎用)、硫酸钾K2SO4(含K2O 50%/适合忌氯作物如烟草/马铃薯/葡萄)。(4)复合肥:磷酸二铵(NH4)2HPO4(N-P2O5:18-46)、磷酸二氢钾KH2PO4(叶面肥/含P2O5 52%+K2O 34%)。\n\n【具体例子】\n尿素施入土壤后经脲酶水解为NH4+才能被吸收,故肥效比硝态氮慢但持久。忌氯作物(烟草/马铃薯/甘薯/甜菜/葡萄)不能用KCl须用K2SO4否则品质下降。\n\n【考点提示·笔试】\n必考:写出3种常用化肥名称+养分含量+性质。辨析:忌氯作物有哪些(烟草/马铃薯/甘薯等)→用K2SO4不用KCl。' WHERE id=@n1;
UPDATE knowledge_nodes SET content='# 有机肥(粪尿肥/堆肥/绿肥)\n\n【一句话定义】\n有机肥是含有大量有机物质的肥料,种类:(1)粪尿肥(人粪尿/畜禽粪→含N/P/K较丰富/须腐熟后施用否则烧苗)(2)堆沤肥(秸秆/杂草/垃圾堆积腐熟而成→有机质含量高/改良土壤效果好)(3)绿肥(将绿色植物体直接翻压入土→如紫云英/苕子/田菁/草木樨→豆科绿肥可固氮增加土壤N素)(4)饼肥(大豆饼/菜籽饼→有机质+N+P+K/优质有机肥)。有机肥特点:肥效缓而持久/改良土壤结构/养分全面但浓度低。\n\n【具体例子】\n水稻田冬种紫云英(绿肥)→春季翻压→提供有机质+N素→减少化肥用量。蔬菜大棚每年基施腐熟鸡粪→改善土壤结构+提供全面养分。\n\n【考点提示·笔试】\n简答:有机肥的优点(至少3点)和注意事项(须腐熟)。辨析:绿肥属于有机肥→主要作用是增加有机质和N素。' WHERE id=@n2;
UPDATE knowledge_nodes SET content='# 施肥方法与测土配方\n\n【一句话定义】\n施肥方法:(1)基肥(播种前整地时施入/以有机肥为主配合磷钾肥)(2)种肥(播种同时施在种子附近/注意浓度不能过高/常用少量化肥)(3)追肥(作物生长期间施入/以氮肥为主/看苗追肥)。测土配方施肥:取土样→化验养分含量→根据目标产量需肥量-土壤供肥量=施肥量→按需配方施用。核心原则:"缺什么补什么,缺多少补多少"。\n\n【具体例子】\n小麦基肥:亩施有机肥2000kg+过磷酸钙50kg+氯化钾10kg;返青追肥:亩施尿素10~15kg。测土配方施肥比农民习惯施肥可节肥20%~30%,增产10%以上。\n\n【考点提示·笔试】\n必考:简述测土配方施肥的步骤和核心原则。辨析:基肥(播种前)/种肥(播种时)/追肥(生长期)的施用时期和肥料类型选择。' WHERE id=@n3;

